SELECT ?actor WHERE {
  ?wonderWomanMovie wdt:P31 wd:Q11424;  # instance of film
                     rdfs:label "Wonder Woman"@en;
                     wdt:P571 ?wwReleaseDate.
  FILTER(YEAR(?wwReleaseDate) = 2017)

  ?actor wdt:P161 ?wonderWomanMovie.  # actor in Wonder Woman

  ?anomalisaMovie wdt:P31 wd:Q11424;
                  rdfs:label "Anomalisa"@en;
                  wdt:P577 ?anomalisaReleaseDate.
  ?anomalisaMovie wdt:P161 ?actor.  # actor in Anomalisa

  ?fargoSeries wdt:P31 wd:Q5398426;
                rdfs:label "Fargo"@en;
                wdt:P577 ?fargoPremiereDate.

  FILTER(?anomalisaReleaseDate > ?fargoPremiereDate)
}
LIMIT 1

