SELECT ?player ?birthplace ?sport WHERE {
  {
    ?player wdt:P31 wd:Q5;              # instance of human
            rdfs:label "Angelique Kerber"@en;
            wdt:P19 ?birthplace;        # place of birth
            wdt:P641 ?sport.            # sport played
    FILTER(CONTAINS(LCASE(STR(?birthplace)), "texas") || EXISTS { ?birthplace wdt:P131* wd:Q1439 }) # Texas or sublocations
  }
  UNION
  {
    ?tournament wdt:P31 wd:Q847017;     # instance of tennis tournament
                rdfs:label "2005 China Open – Men's Doubles"@en.
    ?defendingChampion wdt:P166 ?tournament; # award winner for tournament
                      wdt:P641 wd:Q5372.   # sport is tennis
  }
} 

LIMIT 10

